from rcb_client import Robot
import numpy as np
r=Robot(); o=r.observe(images=['robot_wrist'])
im=o['images']['robot_wrist']; d=o['depth']['robot_wrist']; q=o['proprio']['arm_pos']
m=((im[:,:,0]>35)&(im[:,:,0]>im[:,:,1]*1.35)&(im[:,:,1]<100)&(im[:,:,2]<100))
H,W=m.shape; seen=np.zeros_like(m); comps=[]
for v,u in zip(*np.where(m)):
 if seen[v,u]:continue
 stack=[(v,u)];seen[v,u]=1;pts=[]
 while stack:
  y,x=stack.pop();pts.append((y,x))
  for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
   if 0<=yy<H and 0<=xx<W and m[yy,xx] and not seen[yy,xx]:seen[yy,xx]=1;stack.append((yy,xx))
 if len(pts)>=4: comps.append(pts)
p=np.array([[.1199,0,.5512],[.1199,-.0054,.6796],[.1199,-.0117,.89],[.1199,-.0181,1.1004],[.1199,-.0245,1.3088],[.1199,-.0247,1.4147],[.1199,-.0249,1.5207]])
axes=np.array([[0,0,-1],[0,1,0],[0,0,-1],[0,1,0],[0,0,-1],[0,1,0],[0,0,-1]])
def R(a,t):
 a=a/np.linalg.norm(a); x,y,z=a; c=np.cos(t); s=np.sin(t); C=1-c
 return np.array([[c+x*x*C,x*y*C-z*s,x*z*C+y*s],[y*x+z*s,c+y*y*C,y*z*C-x*s],[z*x-y*s,z*y+x*s,c+z*z*C]])
T=np.eye(4); last=np.zeros(3)
for i in range(7):
 T[:3,3]+=T[:3,:3]@(p[i]-last); T[:3,:3]=T[:3,:3]@R(axes[i],q[i]); last=p[i]
Tcam=T.copy(); Tcam[:3,3]+=Tcam[:3,:3]@np.array([0,0,.0584])
fx=480/(2*np.tan(np.deg2rad(41.8/2)))
print('q=',q,'camera',Tcam[:3,3], 'fx',fx,'components',len(comps))
for pts in sorted(comps,key=len,reverse=True):
 v,u=np.mean(pts,axis=0); dep=float(d[int(round(v)),int(round(u))]);
 if dep==0:dep=float(np.median([d[y,x] for y,x in pts]))
 cam=np.array([-(u-320)/fx*dep, -(v-240)/fx*dep, dep]); world=Tcam[:3,3]+Tcam[:3,:3]@cam
 print(f'{len(pts):3d} px @({u:6.1f},{v:6.1f}) d={dep:.3f} world={world.round(3)}')
