LIM=[None,(-2.24,2.24),None,(-2.57,2.57),None,(-2.09,2.09),None]
def rot(v,t):
 v=v/np.linalg.norm(v);x,y,z=v;c=np.cos(t);s=np.sin(t);C=1-c
 return np.array([[c+x*x*C,x*y*C-z*s,x*z*C+y*s],[y*x+z*s,c+y*y*C,y*z*C-x*s],[z*x-y*s,z*y+x*s,c+z*z*C]])
def fk(q):
 T=np.eye(4);last=np.zeros(3)
 for i in range(7):T[:3,3]+=T[:3,:3]@(P[i]-last);T[:3,:3]=T[:3,:3]@rot(AX[i],q[i]);last=P[i]
 return T[:3,3]+T[:3,:3]@np.array([0,0,.2054])
def ik(goal,seed):
